/bin/zsh -lc "cat .agents/skills/stdo-work/references/recovery.md && python3 -B - <<'PY'
import pathlib,hashlib,json,shutil
root=pathlib.Path.cwd()
files={}
for p in sorted(root.rglob('*')):
    if p.is_symlink():
        files[str(p.relative_to(root))]={'symlink':str(p.readlink())}
    elif p.is_file():
        b=p.read_bytes()
        files[str(p.relative_to(root))]={'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)}
print(json.dumps({'files':files,'stdo_executable':shutil.which('stdo')},indent=2))
for name in ['outputs/diagnostics.md','outputs/built-message.txt','cases/alpha/outputs/greeting.txt','cases/beta/outputs/greeting.txt','cases/gamma/outputs/greeting.txt','cases/alpha/inputs/name.txt','cases/beta/inputs/name.txt','cases/gamma/inputs/name.txt','unrelated/sentinel.txt']:
    print(json.dumps({'path':name,'text':(root/name).read_text()}))
PY"

